package com.guocheng.mediapocket;
public class FullscreenRulesTest {
 static void check(boolean b,String m){if(!b)throw new AssertionError(m);}
 public static void main(String[]args){check(FullscreenRules.mode("crop",false).equals("stretch"),"upgrade stops previous crop mode");check(FullscreenRules.mode("fit",false).equals("stretch"),"requested full-frame default");check(FullscreenRules.zoom("stretch",1.35f)==1f,"old pinch zoom must not crop full frame");check(FullscreenRules.mode("fit",true).equals("fit"),"later explicit original-ratio selection retained");check(FullscreenRules.zoom("fit",1.25f)==1.25f,"manual zoom in other modes retained");check(FullscreenRules.mode("invalid",true).equals("stretch"),"invalid mode defaults safely");check(FullscreenRules.mode("original",true).equals("original"),"original mode remembered");check(FullscreenRules.layoutMode("original").equals("fit")&&FullscreenRules.layoutMode("crop").equals("crop"),"layout mapping");check(FullscreenRules.originalScale(1920,1280)>0.66f&&FullscreenRules.originalScale(1000,1920)==1f,"original pixel scale capped");float[] h=FullscreenRules.axisScale(300,200,10,10);check(h[0]==1.5f&&h[1]==1f,"horizontal pinch only X");float[] v=FullscreenRules.axisScale(10,10,150,100);check(v[0]==1f&&v[1]==1.5f,"vertical pinch only Y");float[] dg=FullscreenRules.axisScale(240,200,120,100);check(dg[0]==1.2f&&dg[1]==1.2f,"diagonal both");check(FullscreenRules.zoomLabel(1f,1f).equals("1.0x")&&FullscreenRules.zoomLabel(1.2f,1f).equals("自定义")&&FullscreenRules.zoomLabel(1.5f,1.5f).equals("1.5x"),"zoom label");check(FullscreenRules.pipRatio(4000,100)<2.39f&&FullscreenRules.pipRatio(0,0)>1.7f,"pip ratio clamp");check(FullscreenRules.ICONS.length==FullscreenRules.MODES.length,"icons");check(FullscreenRules.clamp(9f)==3f&&FullscreenRules.clamp(0.1f)==0.5f&&FullscreenRules.clamp(Float.NaN)==1f,"clamp");check(FullscreenRules.MODES.length==FullscreenRules.LABELS.length,"labels");check(FullscreenRules.next("fit").equals("crop")&&FullscreenRules.next("original").equals("fit"),"cycle order");System.out.println("PASS: zoom label, PiP ratio, free two-axis pinch, cycle order, six aspect modes, axis-independent pinch, clamp, full-frame default migration, old crop/pinch reset, subsequent explicit aspect choice retained.");}
}
